import {readABCText} from '/abc-material.js';
import {api,openCloudState,saveCloudState,flushCloudState} from '/cloud-state.js';
import {storeAudio,readAudio,audioURL} from '/training-audio-store.js';
import {uploadedAudioAssets} from '/voice-library.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const svg=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const size=n=>n<1024?n+' B':n<1048576?(n/1024).toFixed(0)+' KB':(n/1048576).toFixed(1)+' MB';
export function initUploads({toast,onPlay,isPlaying,onPreviewABC,onChange}){
 const root=document.querySelector('#uploads-content');let assets=[],meta={items:[]},query='',sort='newest',trash=false,loaded=false,busy=false,error='',queue=[];
 root.innerHTML=`<div class="view-heading"><div><span class="micro-label">YOUR PERSONAL MATERIAL ARCHIVE</span><h2>上传素材</h2><p>归档音乐、语音与 ABC 乐谱，让下一次创作从这里开始。</p></div><button class="primary-button" id="upload-pick">${svg('upload')}上传素材</button></div><div class="upload-summary"><div class="glass"><span>音乐素材</span><strong id="upload-music-count">0</strong><small>旋律、完整歌曲与伴奏</small></div><div class="glass"><span>语音素材</span><strong id="upload-speech-count">0</strong><small>对白、旁白与音色参考</small></div><div class="glass"><span>ABC 乐谱</span><strong id="upload-abc-count">0</strong><small>旋律、曲谱与编曲参考</small></div><div class="glass"><span>素材空间</span><strong id="upload-size">0 MB</strong><small>文件保存在你的云端空间</small></div></div><div class="upload-toolbar"><label class="upload-search glass">${svg('search')}<input id="upload-search" type="search" placeholder="搜索文件名称…" aria-label="搜索上传素材"></label><select id="upload-sort" aria-label="素材排序"><option value="newest">最近上传</option><option value="name">名称顺序</option><option value="size">文件大小</option></select></div><button class="upload-drop glass" id="upload-drop"><span class="upload-drop-icon">${svg('upload')}</span><strong>把声音与乐谱收藏在这里</strong><span>拖入音乐、语音或 ABC 乐谱，或点击上传</span></button><input id="upload-files" type="file" accept=".wav,.mp3,.flac,.m4a,.ogg,.aac,.abc,.txt,.md" multiple hidden><div id="upload-queue" role="status" aria-live="polite"></div><div class="upload-list-heading"><span id="upload-list-label">全部素材</span><span id="upload-result-count"></span></div><div id="upload-list"></div><p class="upload-footnote">音乐、语音与 ABC 乐谱统一展示，类型分别保存。移入回收站后可恢复，文件仍占用存储空间。</p><dialog id="upload-rename-dialog" class="upload-dialog glass"><form method="dialog"><h3>编辑素材名称</h3><label>显示名称<input id="upload-new-name" maxlength="120" required></label><p>原始文件与下载文件名保持不变。</p><div><button value="cancel" class="outline-button">取消</button><button value="save" class="primary-button">保存</button></div></form></dialog><dialog id="upload-confirm-dialog" class="upload-dialog glass"><form id="upload-confirm-form"><span class="micro-label">ADD TO YOUR COLLECTION</span><h3>收藏新素材</h3><p id="upload-confirm-count"></p><label id="upload-audio-kind-field">这些音频属于<select id="upload-audio-kind"><option value="music">音乐 · 歌曲、旋律与伴奏</option><option value="speech">语音 · 对白、旁白与音色参考</option></select></label><p>ABC、TXT 与 MD 乐谱会自动归档为 ABC。音频最多 100 MB，乐谱最多 200 KB / 50000 字符。</p><div><button type="button" id="upload-cancel" class="outline-button">取消</button><button type="submit" class="primary-button">上传并收藏</button></div></form></dialog>`;
 const assetType=a=>a.kind.slice(7),label=a=>({music:'音乐',speech:'语音',abc:'ABC 乐谱'})[assetType(a)];
 const $=s=>root.querySelector(s),item=id=>meta.items.find(i=>i.id===id),title=a=>item(a.id)?.name||a.name;
 function update(id,patch){let m=item(id);if(!m){m={id};meta.items.push(m);}Object.assign(m,patch);saveCloudState('uploads',meta);window.dispatchEvent(new CustomEvent('sanzo-cloud-update',{detail:{namespace:'uploads',data:meta}}));render();}
 function card(a){
  const type=assetType(a),score=type==='abc',playing=!score&&isPlaying(a.id);
  const visual=score?'<div class="upload-score-lines" aria-hidden="true"><span>♩</span><span>♫</span><span>♪</span></div>':'<div class="upload-signal" aria-hidden="true">'+Array.from({length:29},(_,i)=>'<i style="--bar:'+ (18+((i*17+type.length*13)%65)) +'%"></i>').join('')+'</div>';
  return `<article class="upload-file glass ${type} ${playing?'is-playing':''}"><div class="upload-art ${type}"><span class="upload-type-badge">${svg(score?'score':type==='music'?'music':'voice')}${label(a)}</span>${visual}<button class="upload-file-play ${type}" ${score?'data-upload-preview':'data-upload-play'}="${esc(a.id)}" aria-label="${score?'预览乐谱':playing?'暂停':'播放'} ${esc(title(a))}" ${trash?'disabled':''}>${svg(score?'score':playing?'pause':'play')}<span>${score?'预览乐谱':playing?'正在播放':'播放音频'}</span></button></div><div class="upload-file-info"><h3 title="${esc(title(a))}">${esc(title(a))}</h3><p>${esc(a.name.split('.').pop().toUpperCase())}<span class="upload-dot">·</span>${size(a.bytes)}</p><span class="upload-date">${esc(new Date(a.created_at).toLocaleDateString('zh-CN'))} 上传</span></div><div class="upload-file-actions">${trash?`<button class="outline-button" data-upload-restore="${esc(a.id)}">${svg('upload')}恢复素材</button>`:`<button data-upload-rename="${esc(a.id)}" aria-label="重命名 ${esc(title(a))}" title="重命名">${svg('create')}</button><button data-upload-download="${esc(a.id)}" aria-label="下载 ${esc(title(a))}" title="下载"><svg viewBox="0 0 24 24"><path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/></svg></button><button data-upload-remove="${esc(a.id)}" aria-label="移入回收站 ${esc(title(a))}" title="移入回收站">${svg('trash')}</button>`}</div></article>`;
 }
 function render(){onChange?.();
  const visible=assets.filter(a=>!item(a.id)?.trashed);$('#upload-music-count').textContent=visible.filter(a=>a.kind==='upload-music').length;$('#upload-speech-count').textContent=visible.filter(a=>a.kind==='upload-speech').length;$('#upload-abc-count').textContent=visible.filter(a=>a.kind==='upload-abc').length;$('#upload-size').textContent=size(assets.reduce((n,a)=>n+a.bytes,0));
  $('#upload-pick').innerHTML=svg('upload')+(busy?'上传中…':'上传素材');$('#upload-pick').disabled=busy;$('#upload-drop').disabled=busy;
  $('#upload-list-label').textContent=trash?'素材回收站':'全部素材';
  const list=assets.filter(a=>!!item(a.id)?.trashed===trash&&title(a).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='name'?title(a).localeCompare(title(b),'zh'):sort==='size'?b.bytes-a.bytes:b.created_at.localeCompare(a.created_at));
  $('#upload-result-count').textContent=list.length+' 个文件';
  $('#upload-queue').innerHTML=queue.map(q=>`<div class="upload-queue-item"><span>${esc(q.name)}</span><small class="${q.failed?'failed':''}">${esc(q.status)}</small></div>`).join('');
  $('#upload-list').innerHTML=error?`<div class="upload-empty glass"><h3>暂时无法加载素材</h3><p>${esc(error)}</p><button id="upload-retry" class="outline-button">重新加载</button></div>`:!loaded?'<div class="upload-empty glass">正在读取云端素材…</div>':!list.length?`<div class="upload-empty glass">${svg('upload')}<h3>${query?'没有找到匹配的素材':trash?'回收站是空的':'开始收藏你的创作素材'}</h3><p>${query?'试试其他关键词。':trash?'移除的素材会放在这里，可随时恢复。':'上传音乐、语音与 ABC 乐谱，在这里播放、预览与整理。'}</p></div>`:list.map(card).join('');
 }
 async function load(){error='';render();try{const [data,state]=await Promise.all([api('/api/assets'),openCloudState('uploads',{items:[]})]);assets=[...uploadedAudioAssets(data.assets),...(data.assets||[]).filter(a=>a.kind==='upload-abc'&&(!a.status||a.status==='ready'))];meta=state;meta.items??=[];loaded=true;}catch(e){error=e.message;}render();}
 async function upload(files,audioKind){if(busy||!files.length)return;if(files.length>20){toast('每次最多上传 20 个文件。');return;}busy=true;queue=Array.from(files,f=>({name:f.name,status:'等待上传'}));render();for(let i=0;i<files.length;i++){const file=files[i],kind=/\.(abc|txt|md)$/i.test(file.name)?'upload-abc':'upload-'+audioKind;try{if(kind==='upload-abc'){if(!/\.(abc|txt|md)$/i.test(file.name)||!file.size||file.size>200000)throw Error('请选择不超过 200 KB 的 ABC、TXT 或 MD 乐谱');readABCText(new Uint8Array(await file.arrayBuffer()));}else if(!/\.(wav|mp3|flac|m4a|ogg|aac)$/i.test(file.name)||!file.size||file.size>100*1048576)throw Error('格式不支持或文件超过 100 MB');queue[i].status='正在上传…';render();const id='upload-'+crypto.randomUUID();await storeAudio(id,file,kind);assets.unshift({id,name:file.name,mime:file.type,bytes:file.size,kind,created_at:new Date().toISOString()});if(kind!=='upload-abc')window.dispatchEvent(new CustomEvent('sanzo-audio-upload',{detail:assets[0]}));queue[i].status='已保存到云端';}catch(e){queue[i].status=e.message;queue[i].failed=true;}render();}busy=false;render();toast('上传完成：'+queue.filter(q=>!q.failed).length+' 个成功，'+queue.filter(q=>q.failed).length+' 个失败。');}
 let staged=[];
 function stage(files){if(busy||!files.length)return;if(files.length>20){toast('每次最多上传 20 个文件。');return;}staged=files;const scores=files.filter(f=>/\.(abc|txt|md)$/i.test(f.name)).length;$('#upload-confirm-count').textContent=files.length+' 个文件 · '+size(files.reduce((n,f)=>n+f.size,0))+(scores?' · '+scores+' 份乐谱':'');$('#upload-audio-kind-field').hidden=scores===files.length;$('#upload-confirm-dialog').showModal();}
 $('#upload-cancel').onclick=()=>$('#upload-confirm-dialog').close();$('#upload-confirm-form').onsubmit=e=>{e.preventDefault();const files=staged;staged=[];$('#upload-confirm-dialog').close();upload(files,$('#upload-audio-kind').value);};
 $('#upload-pick').onclick=$('#upload-drop').onclick=()=>$('#upload-files').click();$('#upload-files').onchange=e=>{stage(Array.from(e.target.files));e.target.value='';};
 $('#upload-drop').ondragover=e=>{e.preventDefault();if(!busy)e.currentTarget.classList.add('dragging');};$('#upload-drop').ondragleave=e=>e.currentTarget.classList.remove('dragging');$('#upload-drop').ondrop=e=>{e.preventDefault();e.currentTarget.classList.remove('dragging');stage(Array.from(e.dataTransfer.files));};
 $('#upload-search').oninput=e=>{query=e.target.value;render();};$('#upload-sort').onchange=e=>{sort=e.target.value;render();};
 let renameId=null;$('#upload-rename-dialog').addEventListener('close',()=>{if($('#upload-rename-dialog').returnValue==='save'&&$('#upload-new-name').value.trim())update(renameId,{name:$('#upload-new-name').value.trim()});});
 root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='upload-retry')load();if(b.dataset.uploadPreview){try{const a=assets.find(a=>a.id===b.dataset.uploadPreview);if(!a||item(a.id)?.trashed)return;const blob=await readAudio(a.id);await onPreviewABC({name:title(a),text:readABCText(new Uint8Array(await blob.arrayBuffer()))});}catch(err){toast(err.message);}return;}if(b.dataset.uploadPlay){onPlay(b.dataset.uploadPlay);return;}if(b.dataset.uploadRemove){if(isPlaying(b.dataset.uploadRemove))onPlay(b.dataset.uploadRemove);update(b.dataset.uploadRemove,{trashed:true});toast('已移入素材回收站，可以恢复。');}if(b.dataset.uploadRestore)update(b.dataset.uploadRestore,{trashed:false});if(b.dataset.uploadRename){renameId=b.dataset.uploadRename;$('#upload-new-name').value=title(assets.find(a=>a.id===renameId));$('#upload-rename-dialog').showModal();}if(b.dataset.uploadDownload){try{const a=assets.find(a=>a.id===b.dataset.uploadDownload),blob=await readAudio(a.id),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=a.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(err){toast(err.message);}}});
 window.addEventListener('sanzo-cloud-update',e=>{if(e.detail.namespace==='uploads'){meta=e.detail.data;meta.items??=[];render();}});
 window.addEventListener('sanzo-audio-upload',e=>{if(!assets.some(a=>a.id===e.detail.id))assets.unshift(e.detail);render();});
 async function purge(ids){await flushCloudState('uploads');let failed=0;for(const id of ids){if(!item(id)?.trashed)continue;try{await api('/api/assets/'+encodeURIComponent(id),{method:'DELETE'});assets=assets.filter(a=>a.id!==id);}catch(e){if(e.status===404)assets=assets.filter(a=>a.id!==id);else failed++;}}render();window.dispatchEvent(new CustomEvent('sanzo-cloud-update',{detail:{namespace:'uploads',data:meta}}));return failed;}
 return {show:()=>load(),refresh:render,trashItems:()=>assets.filter(a=>item(a.id)?.trashed).map(a=>({...a,title:title(a)})),restore:id=>update(id,{trashed:false}),purge,
tracks:()=>assets.filter(a=>a.kind!=='upload-abc'&&!item(a.id)?.trashed).map(a=>({id:a.id,title:title(a),type:a.kind==='upload-music'?'songs':'speech',artist:'我的上传',uploaded:true,art:'liquid-glass.png',audioURL:audioURL(a.id),duration:120,tags:[],lyrics:'',prompt:'',style:a.kind==='upload-music'?'音乐素材':'语音素材'}))};
}
